<script id="pomodoro-core">
/* 核心逻辑：纯 JS，无任何外部依赖，可在浏览器与 Node 中运行 */
(function (root) {
  'use strict';

  var FOCUS = 'focus';
  var BREAK = 'break';

  var DEFAULT_OPTIONS = {
    focusMinutes: 25,
    breakMinutes: 5
  };

  function durationMs(mode, options) {
    var opts = options || DEFAULT_OPTIONS;
    var minutes = mode === BREAK ? opts.breakMinutes : opts.focusMinutes;
    return minutes * 60 * 1000;
  }

  function formatTime(ms) {
    var total = Math.max(0, Math.ceil(ms / 1000));
    var minutes = Math.floor(total / 60);
    var seconds = total % 60;
    return (minutes < 10 ? '0' : '') + minutes + ':' + (seconds < 10 ? '0' : '') + seconds;
  }

  function Pomodoro(options) {
    this.options = {
      focusMinutes: DEFAULT_OPTIONS.focusMinutes,
      breakMinutes: DEFAULT_OPTIONS.breakMinutes
    };
    if (options) {
      if (typeof options.focusMinutes === 'number') this.options.focusMinutes = options.focusMinutes;
      if (typeof options.breakMinutes === 'number') this.options.breakMinutes = options.breakMinutes;
    }
    this.mode = FOCUS;
    this.running = false;
    this.endAt = 0;
    this.remainingMs = durationMs(FOCUS, this.options);
    this.completedFocusCount = 0;
    this.completedBreakCount = 0;
  }

  Pomodoro.prototype.totalMs = function () {
    return durationMs(this.mode, this.options);
  };

  Pomodoro.prototype.isRunning = function () {
    return this.running === true;
  };

  Pomodoro.prototype.start = function (now) {
    if (this.running) return this;
    var t = typeof now === 'number' ? now : Date.now();
    this.endAt = t + this.remainingMs;
    this.running = true;
    return this;
  };

  Pomodoro.prototype.pause = function (now) {
    if (!this.running) return this;
    var t = typeof now === 'number' ? now : Date.now();
    this.remainingMs = Math.max(0, this.endAt - t);
    this.running = false;
    return this;
  };

  Pomodoro.prototype.reset = function () {
    this.running = false;
    this.endAt = 0;
    this.remainingMs = this.totalMs();
    return this;
  };

  Pomodoro.prototype.switchMode = function (mode) {
    if (mode !== FOCUS && mode !== BREAK) throw new Error('未知模式: ' + mode);
    this.mode = mode;
    this.running = false;
    this.endAt = 0;
    this.remainingMs = this.totalMs();
    return this;
  };

  /* 推进到指定时刻，返回 { completed, completedMode, nextMode } */
  Pomodoro.prototype.update = function (now) {
    if (!this.running) {
      return { completed: false, completedMode: null, nextMode: null };
    }
    var t = typeof now === 'number' ? now : Date.now();
    if (t < this.endAt) {
      this.remainingMs = this.endAt - t;
      return { completed: false, completedMode: null, nextMode: null };
    }

    var completedMode = this.mode;
    if (completedMode === FOCUS) this.completedFocusCount += 1;
    else this.completedBreakCount += 1;

    var nextMode = completedMode === FOCUS ? BREAK : FOCUS;
    this.mode = nextMode;
    this.remainingMs = this.totalMs();
    this.endAt = this.running ? t + this.remainingMs : 0;
    return { completed: true, completedMode: completedMode, nextMode: nextMode };
  };

  var api = {
    FOCUS: FOCUS,
    BREAK: BREAK,
    Pomodoro: Pomodoro,
    durationMs: durationMs,
    formatTime: formatTime
  };

  root.PomodoroCore = api;
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
})(typeof globalThis !== 'undefined' ? globalThis : this);
</script>

<script>
(function () {
  'use strict';
  var core = window.PomodoroCore;
  var timer = new core.Pomodoro();
  var CIRC = 2 * Math.PI * 104;
  var display = document.getElementById('display');
  var stateText = document.getElementById('stateText');
  var progress = document.getElementById('progress');
  var focusTab = document.getElementById('focusTab');
  var breakTab = document.getElementById('breakTab');
  var startBtn = document.getElementById('startBtn');
  var pauseBtn = document.getElementById('pauseBtn');
  var resetBtn = document.getElementById('resetBtn');

  function render() {
    display.textContent = core.formatTime(timer.remainingMs);
    var ratio = timer.totalMs() === 0 ? 0 : timer.remainingMs / timer.totalMs();
    progress.style.strokeDashoffset = String(CIRC * (1 - ratio));
    progress.setAttribute('stroke', timer.mode === core.FOCUS ? '#d1495b' : '#2a7f62');
    focusTab.className = 'tab' + (timer.mode === core.FOCUS ? ' active-focus' : '');
    breakTab.className = 'tab' + (timer.mode === core.BREAK ? ' active-break' : '');
    stateText.textContent = timer.isRunning()
      ? (timer.mode === core.FOCUS ? '专注中' : '休息中')
      : (timer.remainingMs === timer.totalMs() ? '准备开始' : '已暂停');
  }

  function tick() {
    var result = timer.update(Date.now());
    if (result.completed) {
      if (result.completedMode === core.FOCUS) {
        try {
          var Ctx = window.AudioContext || window.webkitAudioContext;
          if (Ctx) {
            var ctx = new Ctx();
            var osc = ctx.createOscillator();
            var gain = ctx.createGain();
            osc.connect(gain); gain.connect(ctx.destination);
            osc.frequency.value = 880;
            gain.gain.value = 0.0001;
            osc.start();
            gain.gain.exponentialRampToValueAtTime(0.2, ctx.currentTime + 0.02);
            gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.5);
            osc.stop(ctx.currentTime + 0.5);
          }
        } catch (e) { /* 静音失败不影响计时 */ }
      }
      stateText.textContent = result.completedMode === core.FOCUS ? '专注完成，开始休息' : '休息结束，继续专注';
    }
    render();
  }

  startBtn.addEventListener('click', function () {
    timer.start(Date.now());
    render();
  });
  pauseBtn.addEventListener('click', function () {
    timer.pause(Date.now());
    render();
  });
  resetBtn.addEventListener('click', function () {
    timer.reset();
    render();
  });
  focusTab.addEventListener('click', function () {
    timer.switchMode(core.FOCUS);
    render();
  });
  breakTab.addEventListener('click', function () {
    timer.switchMode(core.BREAK);
    render();
  });
  document.addEventListener('keydown', function (e) {
    if (e.code === 'Space') {
      e.preventDefault();
      if (timer.isRunning()) { timer.pause(Date.now()); } else { timer.start(Date.now()); }
      render();
    } else if (e.key === 'r' || e.key === 'R') {
      timer.reset();
      render();
    }
  });

  setInterval(tick, 250);
  render();
})();
</script>
